@router.get("/api/v1/admin/audit-exports/{job_id}/archive")
def download_audit_archive(
    job_id: str,
    storage: ArchiveStorage = Depends(get_archive_storage),
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    export_job = db.query(AuditExportJob).filter(
        AuditExportJob.id == job_id,
        AuditExportJob.company_id == current_user.company_id
    ).first()
    if not export_job:
        raise HTTPException(status_code=404, detail="Export job not found")
    if export_job.status != "completed":
        raise HTTPException(status_code=400, detail="Export job not yet ready")
    file_stream = storage.open_stream(export_job.storage_path)
    return StreamingResponse(file_stream, media_type="application/gzip", headers={"Content-Disposition": f"attachment; filename=audit_{job_id}.tar.gz"})
